def two_sum(nums: list[int], target: int) -> list[int]:
    first_index = {}
    for j, value in enumerate(nums):
        complement = target - value
        if complement in first_index:
            return [first_index[complement], j]
        if value not in first_index:
            first_index[value] = j
    return []
